  static BibleChapter getJohnChapter(int chapterNum) {
    return BibleChapter(
      bookId: 'JHN',
      chapter: chapterNum,
      verses: _getJohnVerses(chapterNum),
    );
  }

  static List<BibleVerse> _getJohnVerses(int chapter) {
    switch (chapter) {
      case 1:
        return [
          BibleVerse(bookId: 'JHN', chapter: 1, verse: 1, text: 'In the beginning was the Word, and the Word was with God, and the Word was God.'),
          BibleVerse(bookId: 'JHN', chapter: 1, verse: 2, text: 'The same was in the beginning with God.'),
