          BibleVerse(bookId: 'JHN', chapter: 1, verse: 16, text: 'And of his fulness have all we received, and grace for grace.'),
          BibleVerse(bookId: 'JHN', chapter: 1, verse: 17, text: 'For the law was given by Moses, but grace and truth came by Jesus Christ.'),
